const $=s=>document.querySelector(s);const KEY='dugout.save.v1';let baseData,data,state=null,page='dashboard',rosterTab='lineup',leaderTab='teams',busy=false,modal=null,selectedTeam='mlb:119',filter='',starter=null,saveError=false;let newsFilter='all',newsDay='all';
