const team=id=>data.teams.find(t=>t.id===id);const player=id=>data.players.find(p=>p.id===id);const own=()=>rosterFor(state,data,state.teamId);const pct=(h,ab)=>ab?(h/ab).toFixed(3).replace(/^0/,''):'.000';
const badge=(id,size='')=>{const t=team(id);return `<span class="team-badge ${size}" style="--team:${t.color}" title="${esc(t.zh)}" aria-label="${esc(t.zh)}">${esc(t.abbr.slice(0,1).toUpperCase())}</span>`;};
